package com.example.contacts.keys;
import android.content.Context;import android.view.KeyEvent;import android.util.Log;import com.example.contacts.util.AppPrefs;
public final class KeyMapper{
 private KeyMapper(){}
 public enum Action{UP,DOWN,LEFT,RIGHT,SELECT,CALL,BACK,MENU,SOFT_LEFT,SOFT_RIGHT,DIGIT,STAR,POUND,PAGE_UP,PAGE_DOWN,DELETE,OTHER}
 public static class Result{public Action action;public int digit;public Result(Action a,int d){action=a;digit=d;}}
 public static Result map(Context c,KeyEvent e){if(e==null)return new Result(Action.OTHER,-1);int k=e.getKeyCode();Log.d("KeyContacts","key="+k+" action="+e.getAction()+" repeat="+e.getRepeatCount());boolean compat=AppPrefs.bool(c,"soft_compat",false);switch(k){case KeyEvent.KEYCODE_DPAD_UP:return new Result(Action.UP,-1);case KeyEvent.KEYCODE_DPAD_DOWN:return new Result(Action.DOWN,-1);case KeyEvent.KEYCODE_DPAD_LEFT:return new Result(Action.LEFT,-1);case KeyEvent.KEYCODE_DPAD_RIGHT:return new Result(Action.RIGHT,-1);case KeyEvent.KEYCODE_DPAD_CENTER:case KeyEvent.KEYCODE_ENTER:return new Result(Action.SELECT,-1);case KeyEvent.KEYCODE_CALL:return new Result(Action.CALL,-1);case KeyEvent.KEYCODE_ENDCALL:case KeyEvent.KEYCODE_BACK:return new Result(Action.BACK,-1);case KeyEvent.KEYCODE_MENU:return new Result(compat?Action.SOFT_LEFT:Action.MENU,-1);case KeyEvent.KEYCODE_SOFT_LEFT:return new Result(Action.SOFT_LEFT,-1);case KeyEvent.KEYCODE_SOFT_RIGHT:return new Result(compat?Action.BACK:Action.SOFT_RIGHT,-1);case KeyEvent.KEYCODE_STAR:return new Result(Action.STAR,-1);case KeyEvent.KEYCODE_POUND:return new Result(Action.POUND,-1);case KeyEvent.KEYCODE_DEL:return new Result(Action.DELETE,-1);case KeyEvent.KEYCODE_VOLUME_UP:return new Result(Action.PAGE_UP,-1);case KeyEvent.KEYCODE_VOLUME_DOWN:return new Result(Action.PAGE_DOWN,-1);default:if(k>=KeyEvent.KEYCODE_0&&k<=KeyEvent.KEYCODE_9)return new Result(Action.DIGIT,k-KeyEvent.KEYCODE_0);}return new Result(Action.OTHER,-1);}
}